// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1 ether);
        vm.assume(actor != address(0));

        Reverter receiver = new Reverter();

        // this contract deployed c, so msg.sender at construction was address(this) == owner
        vm.deal(address(c), amount);

        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if sendTo completes without reverting while the receiver
        // reverts in its fallback, the transfer did NOT happen; a correct contract
        // must revert itself (ok == false). The mutant ignores the failed call's
        // return value and reports success (ok == true) with funds undelivered.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
